import{_ as e,o,c as t,a5 as a}from"./chunks/framework.CXroN2RO.js";const s="/study/images/browser/cross-origin-isolation-boundaries.svg",i="/study/images/browser/shared-array-buffer-observation.svg",f=JSON.parse('{"title":"クロスオリジン分離と共有メモリ — COOP・COEPからSharedArrayBufferまで","description":"","frontmatter":{"title":"クロスオリジン分離と共有メモリ — COOP・COEPからSharedArrayBufferまで","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"ウィンドウのグループとリソースの読み込みを制御するCOOP・COEP・CORPを区別し、Workerとメモリを共有する条件とAtomicsを説明する。","aliases":["クロスオリジン分離","cross-origin isolation","crossOriginIsolated","COOP","COEP","CORP","require-corp","credentialless","Permissions Policy","SharedArrayBuffer","共有メモリ","Atomics"],"verification":"WHATWG HTML・Fetch、W3C Secure Contexts・Permissions Policy、ECMAScriptと照合（2026-11-05）"}},"headers":[],"relativePath":"browser/cross-origin-isolation.md","filePath":"browser/cross-origin-isolation.md"}'),c={name:"browser/cross-origin-isolation.md"};function d(n,r,l,h,p,g){return o(),t("div",null,[...r[0]||(r[0]=[a('<h1 id="クロスオリジン分離と共有メモリ-—-coop・coepからsharedarraybufferまで" tabindex="-1">クロスオリジン分離と共有メモリ — COOP・COEPからSharedArrayBufferまで <a class="header-anchor" href="#クロスオリジン分離と共有メモリ-—-coop・coepからsharedarraybufferまで" aria-label="Permalink to &quot;クロスオリジン分離と共有メモリ — COOP・COEPからSharedArrayBufferまで&quot;">​</a></h1><p><strong>クロスオリジン分離</strong>（cross-origin isolation）は、あるページがウィンドウを開く関係と、ページに取り込めるリソースの条件をブラウザが制限する仕組みです。Workerと共有するカウンターは、処理時間の短い差を測って他の情報を推測するサイドチャネル攻撃にも使えます。ブラウザは共有メモリを使う環境に追加の分離を求めます。現在のページやWorkerで分離が有効かは <code>crossOriginIsolated</code> で観測できます。<a href="https://w3c.github.io/hr-time/#clock-resolution" target="_blank" rel="noreferrer">W3C High Resolution Timeの安全性</a>、<a href="https://html.spec.whatwg.org/multipage/webappapis.html#dom-crossoriginisolated" target="_blank" rel="noreferrer">WHATWG HTMLのcrossOriginIsolated</a></p><h2 id="ウィンドウとリソースで効く場所が違う" tabindex="-1">ウィンドウとリソースで効く場所が違う <a class="header-anchor" href="#ウィンドウとリソースで効く場所が違う" aria-label="Permalink to &quot;ウィンドウとリソースで効く場所が違う&quot;">​</a></h2><table tabindex="0"><thead><tr><th>応答ヘッダー</th><th>どの応答で指定するか</th><th>ブラウザが判断すること</th></tr></thead><tbody><tr><td><code>Cross-Origin-Opener-Policy</code>（COOP）</td><td>トップレベル文書</td><td>画面遷移やポップアップをどの閲覧コンテキストグループに置くか</td></tr><tr><td><code>Cross-Origin-Embedder-Policy</code>（COEP）</td><td>文書やWorkerの入口</td><td>別オリジンのリソースや子文書を取り込めるか</td></tr><tr><td><code>Cross-Origin-Resource-Policy</code>（CORP）</td><td>画像など、取り込まれる側のリソース</td><td>どのオリジンからの <code>no-cors</code> の取得で応答を利用できるか</td></tr></tbody></table><p>COOPの <code>same-origin</code> を指定したトップレベル文書は、オリジンや相手の方針が合わない場合に、開いた側と別の<strong>閲覧コンテキストグループ</strong>へ移ります。例えば別オリジンの認証ポップアップがグループを離れると、<code>window.opener</code> を通じた連絡が途切れることがあります。ヘッダーを導入する際は、ログインなど既存のポップアップ連携も確認します。<a href="https://html.spec.whatwg.org/multipage/browsers.html#cross-origin-opener-policies" target="_blank" rel="noreferrer">WHATWG HTMLのCOOPとグループの切り替え</a></p><p>COEPの <code>require-corp</code> では、別オリジンのリソースを取り込む場合、CORSの検査を通る経路か、配信元がCORPで許可する <code>no-cors</code> の経路が必要です。 <code>credentialless</code> を使うと、別オリジンへの <code>no-cors</code> リクエストからCookieなどの資格情報を外し、CORPヘッダーのない応答も利用できる場合があります。配信元がCORPで拒否していれば、その制限も適用されます。子文書やWorkerの入口ではさらに、それぞれの埋め込み方針も検査されます。<a href="https://html.spec.whatwg.org/multipage/browsers.html#coep" target="_blank" rel="noreferrer">WHATWG HTMLのCOEP</a>、<a href="https://fetch.spec.whatwg.org/#cross-origin-resource-policy-header" target="_blank" rel="noreferrer">WHATWG FetchのCORP検査</a></p><figure class="study-figure"><img src="'+s+`" alt="COOPは開いた側と開かれた側をどの閲覧コンテキストグループに置くかを制御する。COEPは文書やWorkerに入るリソースを検査し、require-corpでは別オリジンの取得にCORSまたはCORPの許可を求める。ブラウザでcrossOriginIsolatedを観測する。" width="760" height="1060" loading="lazy"><figcaption>ウィンドウ同士の関係と、ページが読み込めるリソースを別の境界として見ます。<a href="/study/images/browser/cross-origin-isolation-boundaries.svg" target="_blank" rel="noopener noreferrer">分離の境界を拡大</a></figcaption></figure><h2 id="corpとcorsは要求モードを見て使い分ける" tabindex="-1">CORPとCORSは要求モードを見て使い分ける <a class="header-anchor" href="#corpとcorsは要求モードを見て使い分ける" aria-label="Permalink to &quot;CORPとCORSは要求モードを見て使い分ける&quot;">​</a></h2><p>例えば別オリジンの画像に <code>&lt;img src=&quot;...&quot;&gt;</code> でアクセスすると、通常は <code>no-cors</code> の要求です。COEPが <code>require-corp</code> のページでは、その画像の応答に <code>Cross-Origin-Resource-Policy: cross-origin</code> があれば、CORPの検査を通ります。 <code>same-origin</code> は同一オリジンに、 <code>same-site</code> は同じサイトの範囲に制限します。 <code>same-site</code> では通信の安全性も比較し、HTTPSで届いた応答を非HTTPSの要求元に許可しません。<a href="https://fetch.spec.whatwg.org/#cross-origin-resource-policy-header" target="_blank" rel="noreferrer">WHATWG FetchのCORPヘッダー</a></p><p><code>&lt;img crossorigin=&quot;anonymous&quot; src=&quot;...&quot;&gt;</code> を使うと要求は <code>cors</code> になり、画像の応答にはCORSの許可が必要です。 <code>Access-Control-Allow-Origin</code> が示すのは、CORSの検査で応答を利用できる要求元です。CORPで画像の <code>no-cors</code> 読み込みを許可した場合、画像を表示できても、キャンバスに描いたピクセルをJavaScriptで読み出すにはCORSを通す必要があります。<a href="https://html.spec.whatwg.org/multipage/urls-and-fetching.html#cors-settings-attributes" target="_blank" rel="noreferrer">WHATWG HTMLのcrossorigin属性</a>、<a href="https://html.spec.whatwg.org/multipage/canvas.html#security-with-canvas-elements" target="_blank" rel="noreferrer">キャンバスのセキュリティ</a>、<a href="/study/browser/same-origin-cors.html">同一オリジンポリシーとCORS</a></p><h2 id="共有できる環境を応答ヘッダーと実行結果で確認する" tabindex="-1">共有できる環境を応答ヘッダーと実行結果で確認する <a class="header-anchor" href="#共有できる環境を応答ヘッダーと実行結果で確認する" aria-label="Permalink to &quot;共有できる環境を応答ヘッダーと実行結果で確認する&quot;">​</a></h2><p>トップレベル文書を分離する構成の一例です。ヘッダーはHTTP応答に設定します。</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cross-Origin-Opener-Policy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> same-origin</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cross-Origin-Embedder-Policy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require-corp</span></span></code></pre></div><p>ブラウザがこの方針を扱える<strong>セキュアコンテキスト</strong>で開きます。公開ページなら通常はHTTPSを使い、ループバックの <code>http://127.0.0.1</code> も信頼できる開発用オリジンとして扱われます。 <code>cross-origin-isolated</code> のPermissions Policyが機能を許可していることも条件です。既定の許可範囲は <code>self</code> で、親から機能を制限されたiframeなどでは条件が変わります。ヘッダーを設定した後、ページとWorkerで <code>self.crossOriginIsolated</code> と <code>typeof SharedArrayBuffer</code> を個別に確認します。<a href="https://w3c.github.io/webappsec-secure-contexts/#is-origin-trustworthy" target="_blank" rel="noreferrer">W3C Secure Contexts</a>、<a href="https://html.spec.whatwg.org/multipage/infrastructure.html#cross-origin-isolated-feature" target="_blank" rel="noreferrer">WHATWG HTMLの制御対象機能</a>、<a href="https://w3c.github.io/webappsec-permissions-policy/#permissions-policy-http-header-field" target="_blank" rel="noreferrer">W3C Permissions Policy</a></p><p>HTTPで配信するDedicated Workerの入口は、起点のスクリプト応答からCOEPが決まります。分離対応のCOEPを指定したページがWorkerを作るなら、この入口にも分離に対応するCOEPを設定します。今回の構成ではWorkerのスクリプト応答にも <code>Cross-Origin-Embedder-Policy: require-corp</code> を付けます。トップレベルのウィンドウに作用するCOOPと、Workerの入口に必要なCOEPを分けて確認できます。<a href="https://html.spec.whatwg.org/multipage/workers.html#run-a-worker" target="_blank" rel="noreferrer">WHATWG HTMLのWorker起動手順</a>、<a href="https://html.spec.whatwg.org/multipage/browsers.html#embedder-policy-checks" target="_blank" rel="noreferrer">埋め込み方針の検査</a></p><h2 id="arraybufferのコピーとsharedarraybufferの共有" tabindex="-1">ArrayBufferのコピーとSharedArrayBufferの共有 <a class="header-anchor" href="#arraybufferのコピーとsharedarraybufferの共有" aria-label="Permalink to &quot;ArrayBufferのコピーとSharedArrayBufferの共有&quot;">​</a></h2><p>通常の <code>ArrayBuffer</code> を <code>postMessage()</code> で送ると、転送リストを指定しない場合は<strong>構造化クローン</strong>でバイト列がコピーされます。送った側と受け取ったWorkerは、別々のメモリを使います。転送リストに入れた場合は所有権を渡すため、送った側のバッファは切り離されます。<a href="https://html.spec.whatwg.org/multipage/structured-data.html#structuredserializeinternal" target="_blank" rel="noreferrer">WHATWG HTMLの構造化シリアライズ</a>、<a href="/study/browser/web-workers-messages.html">Web Workerとメッセージ通信</a></p><p><code>SharedArrayBuffer</code> をメッセージに入れる場合も構造化クローンが使われます。受け取った側に新しいJavaScriptオブジェクトが作られ、元と同じ<strong>共有データブロック</strong>を参照します。バイト列の所有権は移動せず、両側で <code>Int32Array</code> などのビューを作ってアクセスできます。共有できるのは同じエージェントクラスタの範囲です。分離の条件を満たさない環境からのシリアライズは <code>DataCloneError</code> になります。<a href="https://html.spec.whatwg.org/multipage/structured-data.html#structureddeserialize" target="_blank" rel="noreferrer">WHATWG HTMLのシリアライズとデシリアライズ</a>、<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-sharedarraybuffer-objects" target="_blank" rel="noreferrer">ECMAScriptのSharedArrayBuffer</a></p><figure class="study-figure"><img src="`+i+'" alt="初期値0のバッファをページからWorkerへ送り、Workerが1を加える。ArrayBufferのコピーではページ側が0、Worker側が1となる。SharedArrayBufferでは二つのビューが同じ共有データブロックを参照し、Atomicsによる更新後にページ側でも1を読める。" width="760" height="1040" loading="lazy"><figcaption>Worker側の結果に加え、送信後にページ側の元のビューを読むと、コピーと共有の差が分かります。<a href="/study/images/browser/shared-array-buffer-observation.svg" target="_blank" rel="noopener noreferrer">コピーと共有の比較を拡大</a></figcaption></figure><h2 id="atomicsで更新と読み出しを同期する" tabindex="-1">Atomicsで更新と読み出しを同期する <a class="header-anchor" href="#atomicsで更新と読み出しを同期する" aria-label="Permalink to &quot;Atomicsで更新と読み出しを同期する&quot;">​</a></h2><p><code>view[0] += 1</code> は、現在値の読み取り、加算、書き戻しに分かれます。2つのWorkerがともに0を読んでから1を書けば、2回加えたつもりでも結果は1です。 <code>Atomics.add(view, 0, 1)</code> は、対応する整数型ビューの要素に対する読み取りと更新を不可分に行い、<strong>更新前の値</strong>を返します。実験では、Workerから更新完了を受け取って、ページ側で <code>Atomics.load(view, 0)</code> を使ってその要素を読み出します。<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-atomics.add" target="_blank" rel="noreferrer">ECMAScriptのAtomics.add</a>、<a href="https://tc39.es/ecma262/multipage/structured-data.html#sec-atomics.load" target="_blank" rel="noreferrer">Atomics.load</a></p><p>複数の要素をまとめて整合させる場合は、どちらが書き込むか、いつ読み出してよいかも決めます。例えばメッセージで完了を通知し、状態を示すフラグをAtomicsで管理する構成があります。共有バッファを渡した時点と、Workerの書き込みが終わった時点を分けて扱います。<a href="https://tc39.es/ecma262/multipage/memory-model.html#sec-shared-memory-guidelines" target="_blank" rel="noreferrer">ECMAScriptの共有メモリの指針</a>、<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a></p><h2 id="実践との対応" tabindex="-1">実践との対応 <a class="header-anchor" href="#実践との対応" aria-label="Permalink to &quot;実践との対応&quot;">​</a></h2><p>公開サンプルでは、現在の分離状態を確認し、通常の <code>ArrayBuffer</code> をWorkerへコピーした後の値を比較できます。ローカル版では、同じページをヘッダーなし、COOPのみ、COEPのみ、両方ありで配信します。別ポートの画像を読み込んだ結果と、Workerへ共有バッファを渡せる条件を分けて観察します。<a href="/study/practice/browser/cross-origin-isolation-observation.html">クロスオリジン分離と共有メモリを観察する</a></p>',24)])])}const m=e(c,[["render",d]]);export{f as __pageData,m as default};
